import { signal } from 'kerfjs';
import { Toolbar } from '@kerfjs/ui/toolbar';
import { ToolbarControlGroup } from '@kerfjs/ui/toolbar-control-group';
import { SegmentedControl } from '@kerfjs/ui/segmented-control';

type WorkspaceView = 'board' | 'list' | 'timeline';
export function createWorkspaceViewToolbar() {
  const view = signal<WorkspaceView>('board');
  const render = () => <Toolbar label="Workspace controls" center={<ToolbarControlGroup label="Workspace view"><SegmentedControl id="workspace-view" label="Workspace view" appearance="toolbar" value={view.value} action="set-workspace-view" choices={[{ value: 'board', label: 'Board' }, { value: 'list', label: 'List' }, { value: 'timeline', label: 'Timeline' }]} /></ToolbarControlGroup>} />;
  return { render, action(command: string, element: HTMLElement) { const value = element.dataset.segmentValue as WorkspaceView | undefined; if (command === 'set-workspace-view' && value && ['board', 'list', 'timeline'].includes(value)) { view.value = value; } } };
}
